Rails.application.routes.draw do
  get "up" => "rails/health#show", as: :rails_health_check

  namespace :moderate do
    root to: "quizzes#index"
    resources :quizzes do
      resources :questions, only: [:new, :create, :edit, :update, :destroy] do
        member do
          post :move_up
          post :move_down
          patch :toggle_active
        end
      end
      member do
        get :preview, to: "previews#show"
        post "preview/answer", to: "previews#answer", as: :preview_answer
        get "preview/result", to: "previews#result", as: :preview_result
        post "preview/reset", to: "previews#reset", as: :preview_reset
      end
    end
  end

  root to: redirect("/moderate")
end
